1	// CRDT compaction and snapshot reads bound the storage a long-lived document
2	// accumulates in the CRDT state layer. Merges only ever need a small part of
3	// the accepted history: a counter merges from each device's maximum
4	// contribution, a gset from the element union, a register from each device's
5	// latest version and the winner among them, and an orset from its live tags
6	// and the tombstones covering dead ones. Everything else no longer affects
7	// the merged result and can be trimmed.
8	//
9	// Compaction rewrites nothing outside the CRDT tables: it never allocates a
10	// change cursor, never writes a change record and never notifies subscribers,
11	// because the merged value does not move. The trimmed state still reproduces
12	// the exact merge and still answers the submission layer's questions. A
13	// snapshot read reports the merged value together with the number of stored
14	// operations and tombstones; both counts are non-negative and durable across
15	// restarts. The identity table is neither count.
16	
17	package crdt
18	
19	import (
20		"database/sql"
21		"encoding/json"
22		"errors"
23	)
24	
25	// Compact trims every stored operation and tombstone that no longer affects
26	// the document's merged result, in one serialized transaction, and returns the
27	// post-compaction snapshot (byte-for-byte what a snapshot read returns
28	// immediately afterward).
29	//
30	// The gate is enforced exactly as in SubmitOps and before any CRDT content is
31	// observed: an unregistered device yields store.ErrDeviceNotFound and a
32	// revoked device yields store.ErrPermissionDenied, and neither touches any
33	// state. A document with no committed CRDT operation yields ErrNotFound. Any
34	// failure leaves the state untouched.
35	//
36	// Per type, compaction keeps precisely the rows the merge and the submission
37	// checks still read:
38	//
39	//   - counter: each device's maximum contribution (ties keep the
40	//     lexicographically smaller operation id). The per-device maxima table is
41	//     untouched. Each dropped id keeps a device-plus-value identity.
42	//   - gset: a minimal prefix cover of the union, operations considered in
43	//     ascending id order. The union table is untouched. Each dropped id keeps
44	//     a device-plus-elements identity.
45	//   - register: each device's greatest-version operation. Each dropped older
46	//     id keeps a device-plus-version-plus-value identity.
47	//   - orset: live add tags; tombstoned tags are dropped together with the
48	//     tombstones covering them. The operation log is untouched, so replaying
49	//     either one stays idempotent; no identity row is needed.
50	//
51	// Compaction is idempotent: a second run finds nothing to trim and returns
52	// the same snapshot. It commits no change-log row, allocates no cursor and,
53	// because the merged value never moves, notifies no subscriber.
54	func (s *Service) Compact(documentID, deviceID string) (Snapshot, error) {
55		// Serialize with submissions and other compactions: the trim and the
56		// submission checks read the same rows, so they must not interleave.
57		s.mu.Lock()
58		defer s.mu.Unlock()
59	
60		tx, err := s.db.Begin()
61		if err != nil {
62			return Snapshot{}, err
63		}
64		defer func() { _ = tx.Rollback() }()
65	
66		// Registration and permission are enforced before any CRDT content is
67		// observed, so a rejected compaction cannot reveal type or state.
68		if s.gate != nil {
69			if err := s.gate.DeviceAuthorizedTx(tx, documentID, deviceID); err != nil {
70				return Snapshot{}, err
71			}
72		}
73	
74		var docType string
75		err = tx.QueryRow(
76			`SELECT type FROM crdt_documents WHERE document_id = ?`, documentID,
77		).Scan(&docType)
78		switch {
79		case errors.Is(err, sql.ErrNoRows):
80			return Snapshot{}, ErrNotFound
81		case err != nil:
82			return Snapshot{}, err
83		}
84	
85		switch docType {
86		case TypeCounter:
87			if err := compactCounterOps(tx, documentID); err != nil {
88				return Snapshot{}, err
89			}
90		case TypeGSet:
91			if err := compactGSetOps(tx, documentID); err != nil {
92				return Snapshot{}, err
93			}
94		case TypeRegister:
95			if err := compactRegisterOps(tx, documentID); err != nil {
96				return Snapshot{}, err
97			}
98		case TypeORSet:
99			if err := compactORSetOps(tx, documentID); err != nil {
100				return Snapshot{}, err
101			}
102		}
103	
104		if err := tx.Commit(); err != nil {
105			return Snapshot{}, err
106		}
107		// The commit is durable and the submission mutex is still held, so no
108		// submission or compaction can interleave before this read.
109		return s.GetSnapshot(documentID)
110	}
111	
112	// compactCounterOps drops every counter operation superseded by a greater
113	// contribution from the same device, keeping exactly one operation per
114	// device: its maximum contribution, ties broken by the smaller operation id.
115	// Before a row is dropped its identity is retained.
116	func compactCounterOps(tx *sql.Tx, documentID string) error {
117		rows, err := tx.Query(
118			`SELECT id, device_id, value FROM crdt_ops WHERE document_id = ? ORDER BY id ASC`,
119			documentID,
120		)
121		if err != nil {
122			return err
123		}
124		type contribution struct {
125			id    string
126			value int64
127			raw   []byte
128		}
129		best := make(map[string]contribution)
130		var drop []Op
131		for rows.Next() {
132			var id, deviceID string
133			var raw []byte
134			if err := rows.Scan(&id, &deviceID, &raw); err != nil {
135				_ = rows.Close()
136				return err
137			}
138			value, err := decodeCounterValue(raw)
139			if err != nil {
140				_ = rows.Close()
141				return err
142			}
143			// Ids arrive in ascending order, so the first contribution seen at the
144			// device's maximum value carries the smallest id.
145			if cur, ok := best[deviceID]; !ok || value > cur.value {
146				if ok {
147					drop = append(drop, Op{ID: cur.id, DeviceID: deviceID, Value: json.RawMessage(cur.raw)})
148				}
149				best[deviceID] = contribution{id: id, value: value, raw: raw}
150			} else {
151				drop = append(drop, Op{ID: id, DeviceID: deviceID, Value: json.RawMessage(raw)})
152			}
153		}
154		if err := rows.Err(); err != nil {
155			_ = rows.Close()
156			return err
157		}
158		_ = rows.Close()
159	
160		for _, op := range drop {
161			if err := retainIdentity(tx, documentID, TypeCounter, op); err != nil {
162				return err
163			}
164			if _, err := tx.Exec(
165				`DELETE FROM crdt_ops WHERE document_id = ? AND id = ?`,
166				documentID, op.ID,
167			); err != nil {
168				return err
169			}
170		}
171		return nil
172	}
173	
174	// compactGSetOps drops every gset operation whose elements are all covered by
175	// kept operations: operations are considered in ascending id order and one is
176	// kept only when it contributes an element no previously kept operation
177	// covers. A dropped operation's identity is retained before its row is
178	// deleted.
179	func compactGSetOps(tx *sql.Tx, documentID string) error {
180		rows, err := tx.Query(
181			`SELECT id, device_id, value FROM crdt_ops WHERE document_id = ? ORDER BY id ASC`,
182			documentID,
183		)
184		if err != nil {
185			return err
186		}
187		covered := make(map[string]struct{})
188		var drop []Op
189		for rows.Next() {
190			var id, deviceID string
191			var raw []byte
192			if err := rows.Scan(&id, &deviceID, &raw); err != nil {
193				_ = rows.Close()
194				return err
195			}
196			var elements []string
197			if err := json.Unmarshal(raw, &elements); err != nil {
198				_ = rows.Close()
199				return err
200			}
201			keeps := false
202			for _, element := range elements {
203				if _, ok := covered[element]; !ok {
204					keeps = true
205					covered[element] = struct{}{}
206				}
207			}
208			if !keeps {
209				drop = append(drop, Op{ID: id, DeviceID: deviceID, Elements: elements})
210			}
211		}
212		if err := rows.Err(); err != nil {
213			_ = rows.Close()
214			return err
215		}
216		_ = rows.Close()
217	
218		for _, op := range drop {
219			if err := retainIdentity(tx, documentID, TypeGSet, op); err != nil {
220				return err
221			}
222			if _, err := tx.Exec(
223				`DELETE FROM crdt_ops WHERE document_id = ? AND id = ?`,
224				documentID, op.ID,
225			); err != nil {
226				return err
227			}
228		}
229		return nil
230	}
231	
232	// compactRegisterOps drops every register operation superseded by a greater
233	// version from the same device, keeping each device's greatest-version
234	// operation. A dropped operation's identity is retained before its row is
235	// deleted.
236	func compactRegisterOps(tx *sql.Tx, documentID string) error {
237		rows, err := tx.Query(
238			`SELECT id, device_id, version, value FROM crdt_register_ops
239			 WHERE document_id = ?
240			   AND EXISTS (
241				SELECT 1 FROM crdt_register_ops newer
242				WHERE newer.document_id = crdt_register_ops.document_id
243				  AND newer.device_id = crdt_register_ops.device_id
244				  AND newer.version > crdt_register_ops.version
245			   )`,
246			documentID,
247		)
248		if err != nil {
249			return err
250		}
251		var drop []Op
252		for rows.Next() {
253			var op Op
254			if err := rows.Scan(&op.ID, &op.DeviceID, &op.Version, &op.Value); err != nil {
255				_ = rows.Close()
256				return err
257			}
258			drop = append(drop, op)
259		}
260		if err := rows.Err(); err != nil {
261			_ = rows.Close()
262			return err
263		}
264		_ = rows.Close()
265	
266		for _, op := range drop {
267			if err := retainIdentity(tx, documentID, TypeRegister, op); err != nil {
268				return err
269			}
270			if _, err := tx.Exec(
271				`DELETE FROM crdt_register_ops WHERE document_id = ? AND id = ?`,
272				documentID, op.ID,
273			); err != nil {
274				return err
275			}
276		}
277		return nil
278	}
279	
280	// compactORSetOps drops every tombstoned add tag together with every
281	// tombstone: a dead tag and the tombstone covering it cancel out of the
282	// merge, so the live element set is unchanged. The operation log is
283	// untouched.
284	func compactORSetOps(tx *sql.Tx, documentID string) error {
285		if _, err := tx.Exec(
286			`DELETE FROM crdt_orset_tags
287			 WHERE document_id = ?
288			   AND EXISTS (
289				SELECT 1 FROM crdt_orset_tombstones x
290				WHERE x.document_id = crdt_orset_tags.document_id
291				  AND x.element = crdt_orset_tags.element
292				  AND x.op_id = crdt_orset_tags.op_id
293			   )`,
294			documentID,
295		); err != nil {
296			return err
297		}
298		_, err := tx.Exec(
299			`DELETE FROM crdt_orset_tombstones WHERE document_id = ?`,
300			documentID,
301		)
302		return err
303	}
304	
305	// GetSnapshot returns the document's merged CRDT state together with the
306	// number of stored operations and tombstones the merge is derived from. A
307	// document with no committed operations yields ErrNotFound. The read is pure:
308	// it advances no cursor, writes nothing and registers no subscription.
309	func (s *Service) GetSnapshot(documentID string) (Snapshot, error) {
310		state, err := s.GetState(documentID)
311		if err != nil {
312			return Snapshot{}, err
313		}
314		snapshot := Snapshot{Type: state.Type, Value: state.Value}
315	
316		count := func(query string) (int64, error) {
317			var n int64
318			if err := s.db.QueryRow(query, documentID).Scan(&n); err != nil {
319				return 0, err
320			}
321			return n, nil
322		}
323	
324		switch state.Type {
325		case TypeCounter, TypeGSet:
326			operations, err := count(`SELECT COUNT(*) FROM crdt_ops WHERE document_id = ?`)
327			if err != nil {
328				return Snapshot{}, err
329			}
330			snapshot.Operations = operations
331		case TypeRegister:
332			operations, err := count(`SELECT COUNT(*) FROM crdt_register_ops WHERE document_id = ?`)
333			if err != nil {
334				return Snapshot{}, err
335			}
336			snapshot.Operations = operations
337		case TypeORSet:
338			operations, err := count(`SELECT COUNT(*) FROM crdt_orset_tags WHERE document_id = ?`)
339			if err != nil {
340				return Snapshot{}, err
341			}
342			tombstones, err := count(`SELECT COUNT(*) FROM crdt_orset_tombstones WHERE document_id = ?`)
343			if err != nil {
344				return Snapshot{}, err
345			}
346			snapshot.Operations = operations
347			snapshot.Tombstones = tombstones
348		}
349		return snapshot, nil
350	}
351

