328	// Compaction is not a change: a session long poll parked at the tail is not
329	// woken by it and only returns when its own wait deadline expires.
330	func TestSessionCompactDoesNotWakeSessionPoll(t *testing.T) {
331		h, _ := newTestHandler(t)
332		createSessionViaHTTP(t, h, "dev", "sess")
333		seedDoc(t, h, "doc", 3)
334		snapshotViaHTTP(t, h, "doc", 2)
335	
336		type pollResult struct {
337			body    map[string]any
338			elapsed time.Duration
339		}
340		done := make(chan pollResult, 1)
341		go func() {
342			start := time.Now()
343			_, body := doRequest(t, h, http.MethodGet,
344				"/v1/sessions/sess/documents/doc/changes/poll?after=3&waitMs=300")
345			done <- pollResult{body, time.Since(start)}
346		}()
347		time.Sleep(50 * time.Millisecond)
348		if w := postSessionCompact(t, h, "sess", "doc", `{}`); w.Code != http.StatusOK {
349			t.Fatalf("compact = %d %s", w.Code, w.Body.String())
350		}
351		select {
352		case got := <-done:
353			if got.body["timedOut"] != true {
354				t.Fatalf("poll timedOut = %v", got.body)
355			}
356			if next := int64(got.body["nextCursor"].(float64)); next != 3 {
357				t.Fatalf("poll nextCursor = %d, want 3", next)
358			}
359			if got.elapsed < 200*time.Millisecond {
360				t.Fatalf("poll returned after %v: the compaction woke it", got.elapsed)
361			}
362		case <-time.After(3 * time.Second):
363			t.Fatal("poll did not return")
364		}
365	}
